(function(){
'use strict';
var A4k9R=document.getElementById('A4k9R');
var _errEl=document.getElementById('err');
var controller=null,frame=null;
var currentW=null;
try{currentW=localStorage.getItem('wVr1');}catch(e){}
var _swReady=false;
var _initLock=null;
