log('bootstrap',{a762:a762,a764:a764,currentW:currentW});

function _doInitController(){
  if(_initLock)return _initLock;
  _initLock=(async function(){
    log('_doInitController start');
    controller=null;frame=null;
    var Ctrl=window.dGFzazR6MTMzNw&&window.dGFzazR6MTMzNw.Controller;
    var cfg=window.dGFzazR6MTMzNw&&window.dGFzazR6MTMzNw.config;
    if(!Ctrl){throw new Error('dGFzazR6MTMzNw.Controller missing');}
    if(!cfg){throw new Error('dGFzazR6MTMzNw.config missing');}
    if(!window.L1bcTransport||!window.L1bcTransport.L1bcClient){throw new Error('L1bcTransport.L1bcClient missing');}
    cfg.dGFzazQ=a762+a764+'index-c7m2q5.js';
    cfg.dGFza3o=a762+a764+'function-4827316.wasm';
    cfg.ZWR1Y2F0aW9u=a762+a764+'index-l3w5m9.js';
