}

async function doNavigate(url){
  if(!url.startsWith('http'))url='https://'+url;
  log('doNavigate',url,{currentW:currentW,hasFrame:!!frame});
  try{
    if(!navigator.serviceWorker.controller){
      log('waiting for controllerchange');
      await new Promise(function(res){navigator.serviceWorker.addEventListener('controllerchange',res,{once:true});});
      log('controllerchange fired');
    }
    if(!currentW){
      try{currentW=localStorage.getItem('wVr1');}catch(e){}
      log('currentW from localStorage:',currentW);
    }
    if(!currentW){
      log('no currentW, parking nav');
      _pendingNav=url;
      return;
    }
    if(!frame)await _doInitController();
    log('calling frame.go',url);
    await frame.go(url);
    log('frame.go done');
    A4k9R.style.display='block';
    toParent('urlchange',{url:url});
  }catch(err){
    log('doNavigate error',err&&err.message);
    showErr('nav: '+(err&&err.message||err));
  }
}

window.addEventListener('message',function(e){
  var d=e.data;
  if(!d||d.type!=='e:command')return;
  log('command',d.action);
  if(d.action==='navigate'&&d.url)doNavigate(d.url);
  else if(d.action==='back'){try{A4k9R.contentWindow.history.back();}catch(er){}}
  else if(d.action==='forward'){try{A4k9R.contentWindow.history.forward();}catch(er){}}
  else if(d.action==='reload'){try{A4k9R.contentWindow.location.reload();}catch(er){}}
  else if(d.action==='setW1p'&&d.w1p){
    var changed=(d.w1p!==currentW);
    currentW=d.w1p;
    try{localStorage.setItem('wVr1',currentW);}catch(e){}
    log('setW1p',currentW,'changed',changed);
    if(changed){controller=null;frame=null;_initLock=null;}
    _doInitController().then(function(){
      if(_pendingNav){var u=_pendingNav;_pendingNav=null;doNavigate(u);}
    }).catch(function(er){log('setW1p init error',er&&er.message);});
  }
});

/* ---- query parameter handling ---- */
(function(){
  var params;
  try{
    params=new URLSearchParams(EFFECTIVE_LOC.search);
  }catch(e){
    try{
      params=new URLSearchParams(location.search);
    }catch(e2){
      params=new URLSearchParams('');
    }
  }
  var action=null,goUrl=null,w1Url=null;

  function decodeQueryValue(raw){
    if(raw==null)return null;
    var value=String(raw).trim();
    if(!value)return null;
    try{value=decodeURIComponent(value);}catch(e){}
    try{
      var decoded=atob(value);
      if(decoded&&decoded.trim())value=decoded;
    }catch(e){}
    return value;
  }

  function normalizeTarget(value){
    if(!value)return null;
    var target=decodeQueryValue(value);
    if(!target)return null;
    target=target.replace(/^\s+|\s+$/g,'');
    if(!target)return null;
    if(/^https?:\/\//i.test(target)||/^wss?:\/\//i.test(target)||target.indexOf('/')===0||target.indexOf('./')===0||target.indexOf('../')===0){return target;}
    if(/^(?:localhost|[a-z0-9._-]+|\d{1,3}(?:\.\d{1,3}){3})(?::\d+)?(?:[/?#].*)?$/i.test(target)){
      return /^https?:\/\//i.test(target)?target:'https://'+target;
    }
    return null;
  }

  if(params.has('refresh'))action='refresh';
  else if(params.has('back'))action='back';
  else if(params.has('forward'))action='forward';

  if(params.has('go')){
    goUrl=normalizeTarget(params.get('go'));
  }
  if(params.has('w1')){
    w1Url=decodeQueryValue(params.get('w1'));
  }

  log('query params',{action:action,goUrl:goUrl,w1Url:w1Url,search:EFFECTIVE_LOC.search});

  if(!action&&!goUrl&&!w1Url)return;

  if(w1Url){
    var changed=(w1Url!==currentW);
    currentW=w1Url;
    try{localStorage.setItem('wVr1',w1Url);}catch(e){}
    if(changed){controller=null;frame=null;_initLock=null;}
  }

  function fire(){
    log('fire',{w1Url:w1Url,goUrl:goUrl,action:action,_swReady:_swReady});
    // Always try to init if we have a w1 OR we need a frame for navigation.
    if(w1Url||goUrl){
      _doInitController().catch(function(er){log('fire init error',er&&er.message);});
    }
    if(goUrl){
      doNavigate(goUrl);
    }else if(action==='refresh'){
      try{A4k9R.contentWindow.location.reload();}catch(e){}
    }else if(action==='back'){
      try{A4k9R.contentWindow.history.back();}catch(e){}
    }else if(action==='forward'){
      try{A4k9R.contentWindow.history.forward();}catch(e){}
    }
  }

  var done=false;
  function onMsg(e){
    var d=e.data;
    if(d&&d.source==='e'&&(d.type==='e:ready'||d.type==='e:error')){
      if(done)return;done=true;
      window.removeEventListener('message',onMsg);
      fire();
    }
  }
  window.addEventListener('message',onMsg);
  setTimeout(function(){if(!done){done=true;window.removeEventListener('message',onMsg);fire();}},3000);
})();
/* ---- end query parameter handling ---- */

(async function preInit(){
  try{
    if(!navigator.serviceWorker){log('no serviceWorker');return;}
    log('preInit: registering sw');
    await navigator.serviceWorker.register(a762+a764+'index-n6q3m5.js',{scope:a764,updateViaCache:'none'});
