      log('preInit: controller ready');
    }else{
      log('preInit: controller already set');
    }
    _swReady=true;
    if(currentW)await _doInitController();
    toParent('ready');
  }catch(e){
    log('preInit error',e&&e.message);
    showErr('preInit: '+(e&&e.message||e));
  }
})();
